            postNotificationsGranted = false,
            notificationAccessGranted = false,
            batteryOptimizationGranted = false,
            onRequestPostNotifications = {},
            onOpenNotificationAccess = {},
            onRequestDisableBatteryOptimization = {}
        )
    }
}

